class Solution {
public:
    int maximumScore(int a, int b, int c) {
        int t;
        if (a > b) { t = a; a = b; b = t; }
        if (b > c) { t = b; b = c; c = t; }
        if (a > b) { t = a; a = b; b = t; }
        if (a + b <= c) return a + b;
        return (a + b + c) / 2;
    }
};
